package lean

import (
	"bytes"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strconv"
	"strings"
	"testing"

	"github.com/santhosh-tekuri/jsonschema/v6"
)

// The parity tests of the lean JSON schema: the committed file (generated by schema_gen_test.go) is read back here by code that does
// not share the generator's logic, and compared with the struct tags of the model, key by key. Then every valid fixture must
// validate and every schema failure of an invalid fixture must be reported by the decoder at the same place.

func loadSchemaDoc(t *testing.T) map[string]any {
	t.Helper()
	raw, err := os.ReadFile(filepath.FromSlash(schemaPath))
	if err != nil {
		t.Fatal(err)
	}
	var doc map[string]any
	if err := json.Unmarshal(raw, &doc); err != nil {
		t.Fatal(err)
	}
	return doc
}

func compileSchema(t *testing.T) *jsonschema.Schema {
	t.Helper()
	raw, err := os.ReadFile(filepath.FromSlash(schemaPath))
	if err != nil {
		t.Fatal(err)
	}
	doc, err := jsonschema.UnmarshalJSON(bytes.NewReader(raw))
	if err != nil {
		t.Fatal(err)
	}
	c := jsonschema.NewCompiler()
	if err := c.AddResource("battle_companies.schema.json", doc); err != nil {
		t.Fatal(err)
	}
	s, err := c.Compile("battle_companies.schema.json")
	if err != nil {
		t.Fatalf("the schema does not compile: %v", err)
	}
	return s
}

func num(v any) (float64, bool) {
	f, ok := v.(float64)
	return f, ok
}

// tagFloat reads a numeric tag; ok is false when absent.
func tagFloat(sf reflect.StructField, key string) (float64, bool) {
	s, ok := sf.Tag.Lookup(key)
	if !ok {
		return 0, false
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return 0, false
	}
	return f, true
}

func checkBound(t *testing.T, where string, prop map[string]any, key string, tag float64, has bool) {
	t.Helper()
	got, present := num(prop[key])
	switch {
	case has && !present:
		t.Errorf("%s: the model says %s %v, the schema has none", where, key, tag)
	case !has && present:
		t.Errorf("%s: the schema has %s %v, the model has no such bound", where, key, got)
	case has && got != tag:
		t.Errorf("%s: %s is %v in the schema, %v in the model", where, key, got, tag)
	}
}

func checkEnum(t *testing.T, where string, node map[string]any, tag string) {
	t.Helper()
	var want []string
	if tag != "" {
		want = strings.Split(tag, "|")
	}
	var got []string
	if l, ok := node["enum"].([]any); ok {
		for _, v := range l {
			got = append(got, v.(string))
		}
	}
	if !reflect.DeepEqual(want, got) {
		t.Errorf("%s: enum is %v in the schema, %v in the model", where, got, want)
	}
}

// checkProp compares one property schema with the model field.
func checkProp(t *testing.T, where string, sf reflect.StructField, prop map[string]any) {
	t.Helper()
	typ := sf.Type
	nullable := false
	for typ.Kind() == reflect.Pointer {
		typ = typ.Elem()
		nullable = typ.Kind() == reflect.String || typ.Kind() == reflect.Bool
	}
	if _, ok := polymorphic[typ]; ok {
		if prop["$ref"] != "#/$defs/"+typ.Name() {
			t.Errorf("%s: a %s is expected as $ref #/$defs/%s, got %v", where, typ.Name(), typ.Name(), prop)
		}
		return
	}
	jsonType := map[reflect.Kind]string{reflect.String: "string", reflect.Bool: "boolean", reflect.Int: "integer", reflect.Int64: "integer",
		reflect.Float64: "number", reflect.Slice: "array", reflect.Map: "object"}
	switch typ.Kind() {
	case reflect.Interface:
		rest := 0 // the description apart, a Free field accepts anything: it has no type, no range, no $ref
		for k := range prop {
			if k != "description" {
				rest++
			}
		}
		if rest != 0 && !(rest == 1 && prop["default"] != nil) {
			t.Errorf("%s: a Free field must be the empty schema (a description apart), got %v", where, prop)
		}
	case reflect.Struct:
		if prop["$ref"] != "#/$defs/"+typ.Name() {
			t.Errorf("%s: expected $ref #/$defs/%s, got %v", where, typ.Name(), prop["$ref"])
		}
	default:
		want := any(jsonType[typ.Kind()])
		if nullable {
			want = []any{jsonType[typ.Kind()], "null"}
		}
		if !reflect.DeepEqual(prop["type"], want) {
			t.Errorf("%s: type is %v in the schema, %v in the model", where, prop["type"], want)
		}
	}
	lo, hasLo := tagFloat(sf, "min")
	hi, hasHi := tagFloat(sf, "max")
	switch typ.Kind() {
	case reflect.String:
		checkBound(t, where, prop, "minLength", lo, hasLo)
		checkBound(t, where, prop, "maxLength", hi, hasHi)
		if !nullable {
			checkEnum(t, where, prop, sf.Tag.Get("enum"))
		}
	case reflect.Int, reflect.Int64, reflect.Float64:
		checkBound(t, where, prop, "minimum", lo, hasLo)
		checkBound(t, where, prop, "maximum", hi, hasHi)
	case reflect.Slice:
		checkBound(t, where, prop, "minItems", lo, hasLo)
		checkBound(t, where, prop, "maxItems", hi, hasHi)
		items, _ := prop["items"].(map[string]any)
		if items == nil {
			t.Errorf("%s: a list needs items", where)
			return
		}
		elem := typ.Elem()
		for elem.Kind() == reflect.Pointer {
			elem = elem.Elem()
		}
		el := reflect.StructField{Name: sf.Name + "[]", Type: elem}
		var tags []string
		for _, k := range [][2]string{{"enum", "enum"}, {"emin", "min"}, {"emax", "max"}} {
			if v, ok := sf.Tag.Lookup(k[0]); ok {
				tags = append(tags, k[1]+":"+strconv.Quote(v))
			}
		}
		el.Tag = reflect.StructTag(strings.Join(tags, " "))
		checkProp(t, where+"[]", el, items)
	case reflect.Map:
		ap, _ := prop["additionalProperties"].(map[string]any)
		if ap == nil {
			t.Errorf("%s: a map needs additionalProperties", where)
			return
		}
		checkProp(t, where+"{}", reflect.StructField{Name: sf.Name + "{}", Type: typ.Elem()}, ap)
	}
}

// TestSchemaMatchesModel: every key, type, enum, range, required and openness of the model is in the schema and the reverse.
func TestSchemaMatchesModel(t *testing.T) {
	doc := loadSchemaDoc(t)
	defs, _ := doc["$defs"].(map[string]any)
	seen := map[string]bool{}
	var visit func(st reflect.Type, node map[string]any)
	visit = func(st reflect.Type, node map[string]any) {
		if seen[st.Name()] {
			return
		}
		seen[st.Name()] = true
		props, _ := node["properties"].(map[string]any)
		wantReq := map[string]bool{}
		open := false
		modelKeys := map[string]bool{}
		for i := 0; i < st.NumField(); i++ {
			sf := st.Field(i)
			if sf.Tag.Get("rest") == "true" {
				open = true
				continue
			}
			name, _, _ := strings.Cut(sf.Tag.Get("json"), ",")
			if name == "" || name == "-" {
				continue
			}
			modelKeys[name] = true
			where := st.Name() + "." + name
			prop, ok := props[name].(map[string]any)
			if !ok {
				t.Errorf("%s: in the model, missing from the schema", where)
				continue
			}
			if sf.Tag.Get("required") == "true" {
				wantReq[name] = true
			}
			checkProp(t, where, sf, prop)
			// default
			if d, has := prop["default"]; has {
				if want, ok := schemaDefaults[where]; !ok || !reflect.DeepEqual(jsonVal(want), d) {
					t.Errorf("%s: schema default %v is not a default of the decoder (%v)", where, d, want)
				}
			} else if _, ok := schemaDefaults[where]; ok {
				t.Errorf("%s: the decoder defaults it, the schema has no default", where)
			}
			// descend
			typ := sf.Type
			for typ.Kind() == reflect.Pointer || typ.Kind() == reflect.Slice || typ.Kind() == reflect.Map {
				typ = typ.Elem()
			}
			if _, poly := polymorphic[typ]; typ.Kind() == reflect.Struct && !poly {
				sub, ok := defs[typ.Name()].(map[string]any)
				if !ok {
					t.Errorf("%s: no $defs/%s", where, typ.Name())
					continue
				}
				visit(typ, sub)
			}
		}
		for k := range props {
			if !modelKeys[k] {
				t.Errorf("%s.%s: in the schema, not in the model", st.Name(), k)
			}
		}
		var gotReq []string
		reqList, _ := node["required"].([]any)
		for _, r := range reqList {
			gotReq = append(gotReq, r.(string))
		}
		var wantList []string
		for k := range wantReq {
			wantList = append(wantList, k)
		}
		sort.Strings(gotReq)
		sort.Strings(wantList)
		if len(gotReq) != len(wantList) || (len(wantList) > 0 && !reflect.DeepEqual(gotReq, wantList)) {
			t.Errorf("%s: required is %v in the schema, %v in the model", st.Name(), gotReq, wantList)
		}
		if ap, _ := node["additionalProperties"].(bool); ap != open {
			t.Errorf("%s: additionalProperties is %v in the schema, the model has a rest map: %v", st.Name(), ap, open)
		}
	}
	// the root is the Document
	visit(reflect.TypeOf(Document{}), doc)
	// no definition without a model type
	for name := range defs {
		if !seen[name] {
			if _, poly := polyByName(name); !poly {
				t.Errorf("$defs/%s: no such type in the model", name)
			}
		}
	}
	if v, _ := doc["properties"].(map[string]any)["schemaVersion"].(map[string]any); v == nil || v["const"] != float64(SupportedSchemaVersion) {
		t.Errorf("schemaVersion must be const %d (the version this decoder reads), got %v", SupportedSchemaVersion, v)
	}
}

func polyByName(name string) (reflect.Type, bool) {
	for t := range polymorphic {
		if polyName(t) == name {
			return t, true
		}
	}
	return nil, false
}

// jsonVal normalises a Go default to what json.Unmarshal gives.
func jsonVal(v any) any {
	b, _ := json.Marshal(v)
	var out any
	_ = json.Unmarshal(b, &out)
	return out
}

// TestSchemaDefaults: each default of the schema is what Normalise really writes into an absent field.
func TestSchemaDefaults(t *testing.T) {
	doc := &Document{
		Rules:     []Rule{{Name: "R", Target: &Target{}}},
		Paths:     []Path{{Name: "P"}},
		Scenarios: []Scenario{{Name: "S", Scoring: []Scoring{{Key: "k"}}}},
		Companies: []Company{{
			Name: "C", OwnPath: &OwnPath{}, Start: &Start{Units: []StartUnit{{Unit: "u"}}},
			Reinforcements: &Chart{Rows: []ChartRow{{Nothing: true}}},
		}},
	}
	var rep Report
	Normalise(doc, NewReporter("x", &rep))
	got := map[string]any{
		"Path.kind":        doc.Paths[0].Kind,
		"Scenario.side":    doc.Scenarios[0].Side,
		"Scoring.side":     doc.Scenarios[0].Scoring[0].Side,
		"Target.appliesTo": doc.Rules[0].Target.AppliesTo,
		"Target.match":     doc.Rules[0].Target.Match,
		"OwnPath.path":     doc.Companies[0].OwnPath.Path,
		"StartUnit.count":  doc.Companies[0].Start.Units[0].Count,
		"ChartRow.count":   doc.Companies[0].Reinforcements.Rows[0].Count,
	}
	if len(got) != len(schemaDefaults) {
		t.Errorf("schemaDefaults has %d entries, the test checks %d: add the new one here", len(schemaDefaults), len(got))
	}
	for k, want := range schemaDefaults {
		if !reflect.DeepEqual(jsonVal(got[k]), jsonVal(want)) {
			t.Errorf("%s: Normalise writes %v, the schema says %v", k, got[k], want)
		}
	}
}

// schemaLeaves lists the instance locations of the leaf failures of a validation, as lean report paths.
func schemaLeaves(err error) []string {
	var ve *jsonschema.ValidationError
	if !errors.As(err, &ve) {
		return []string{"?" + err.Error()}
	}
	var out []string
	var walk func(*jsonschema.ValidationError)
	walk = func(e *jsonschema.ValidationError) {
		if len(e.Causes) == 0 {
			p := ""
			for _, seg := range e.InstanceLocation {
				if _, err := strconv.Atoi(seg); err == nil {
					p = Idx(p, mustAtoi(seg))
				} else {
					p = Join(p, seg)
				}
			}
			out = append(out, p)
			return
		}
		for _, c := range e.Causes {
			walk(c)
		}
	}
	walk(ve)
	return out
}

func mustAtoi(s string) int { n, _ := strconv.Atoi(s); return n }

// TestFixturesAgainstSchema: every valid fixture validates; every place where the schema rejects an invalid fixture is a place where
// the decoder reports something too (at the path or beneath it), so the two never disagree about where a mistake is.
func TestFixturesAgainstSchema(t *testing.T) {
	schema := compileSchema(t)
	valid, _ := filepath.Glob("testdata/valid/*.json")
	if len(valid) < 10 {
		t.Fatalf("only %d valid fixtures", len(valid))
	}
	for _, f := range valid {
		t.Run("valid/"+filepath.Base(f), func(t *testing.T) {
			raw, _ := os.ReadFile(f)
			inst, err := jsonschema.UnmarshalJSON(bytes.NewReader(raw))
			if err != nil {
				t.Fatal(err)
			}
			if err := schema.Validate(inst); err != nil {
				t.Errorf("a valid fixture fails the schema: %v", schemaLeaves(err))
			}
		})
	}
	rejected := 0
	invalid, _ := filepath.Glob("testdata/invalid/*.json")
	for _, f := range invalid {
		name := strings.TrimSuffix(filepath.Base(f), ".json")
		t.Run("invalid/"+name, func(t *testing.T) {
			raw, _ := os.ReadFile(f)
			inst, err := jsonschema.UnmarshalJSON(bytes.NewReader(raw))
			if err != nil {
				return // not JSON at all (syntax_error): the decoder's business
			}
			err = schema.Validate(inst)
			if err == nil {
				return // a semantic mistake: names, charts, cross references
			}
			rejected++
			want, _ := os.ReadFile(strings.TrimSuffix(f, ".json") + ".want")
			var paths []string
			for _, line := range strings.Split(string(want), "\n") {
				if rest, ok := strings.CutPrefix(line, fixtureFile+": "); ok {
					p, _, _ := strings.Cut(rest, ": ")
					paths = append(paths, p)
				}
			}
			if gated(paths, string(want)) {
				return // the version gate: one message for the whole file, whatever else is wrong
			}
			for _, loc := range schemaLeaves(err) {
				if !reportedAt(paths, loc) {
					t.Errorf("the schema rejects %q but the decoder reports nothing there or beneath it; decoder paths: %v", loc, paths)
				}
			}
		})
	}
	if rejected < 5 {
		t.Errorf("only %d invalid fixtures fail the schema; the comparison is not exercised", rejected)
	}
}

// gated: the decoder stopped at schemaVersion (old format, unknown version), so it says nothing about the rest.
func gated(paths []string, want string) bool {
	return len(paths) > 0 && strings.HasPrefix(paths[0], "schemaVersion") && !strings.Contains(want, "\n"+fixtureFile)
}

// reportedAt: the decoder named loc, something beneath it, or (for a whole-file problem) the root.
func reportedAt(paths []string, loc string) bool {
	if loc == "" {
		return len(paths) > 0
	}
	for _, p := range paths {
		if p == loc || strings.HasPrefix(p, loc+".") || strings.HasPrefix(p, loc+"[") {
			return true
		}
	}
	return false
}

// TestSchemaCompilesStrictly: the schema is a valid Draft 2020-12 schema and rejects the plainest mistakes the decoder rejects.
func TestSchemaRejectsBasics(t *testing.T) {
	schema := compileSchema(t)
	for name, doc := range map[string]string{
		"unknown top-level key": `{"schemaVersion":2,"name":"x","version":"1","campaign":{},"colour":1}`,
		"wrong schemaVersion":   `{"schemaVersion":1,"name":"x","version":"1","campaign":{}}`,
		"no name":               `{"schemaVersion":2,"version":"1","campaign":{}}`,
		"bad enum":              `{"schemaVersion":2,"name":"x","version":"1","campaign":{},"gear":[{"name":"g","kind":"wargaer"}]}`,
		"bad dice":              `{"schemaVersion":2,"name":"x","version":"1","campaign":{},"paths":[{"name":"p","dice":"2d6x"}]}`,
	} {
		inst, err := jsonschema.UnmarshalJSON(strings.NewReader(doc))
		if err != nil {
			t.Fatal(err)
		}
		if schema.Validate(inst) == nil {
			t.Errorf("%s: the schema accepted %s", name, doc)
		}
	}
}
